#!/usr/bin/env bash
# Runs every performance measurement for Obsidium and appends results to .artifacts/benchmarks/.
#
#   scripts/bench/run-all.sh                # 1k / 10k vaults, in-process + end-to-end
#   SIZES=1000,10000,100000 scripts/bench/run-all.sh
#
# Sections:
#   1. in-process core benches (indexing, search pipeline, link pipeline, graph layout)
#   2. end-to-end CLI timings on generated vaults (cold index build, warm search, note read)
#   3. process RSS / CPU for the Tauri app (macOS only, GUI must be able to render)
#
# Test data is generated by scripts/bench/gen-vault.mjs into $VAULT_ROOT (default /tmp/obsidium-bench).
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
SIZES="${SIZES:-1000,10000}"
VAULT_ROOT="${VAULT_ROOT:-/tmp/obsidium-bench}"
TARGET="${CARGO_TARGET_DIR:-$ROOT/../.artifacts/cargo-bench}"
CLI="$TARGET/release/obsidium"
BENCH_OUT="$ROOT/../.artifacts/benchmarks"

mkdir -p "$VAULT_ROOT" "$BENCH_OUT"

echo "== 1. in-process core benches (sizes=$SIZES) =="
(
  cd "$ROOT/src-tauri"
  for bench in benchmark_indexing benchmark_search_pipeline benchmark_link_pipeline benchmark_graph_layout; do
    OBSIDIUM_BENCH_SIZES="$SIZES" CARGO_TARGET_DIR="$TARGET" \
      cargo test --release -p obsidium-core --lib "$bench" -- --ignored --nocapture 2>&1 \
      | grep -E "BENCH-|test result" || true
  done
)

echo "== 2. end-to-end CLI =="
if [ ! -x "$CLI" ]; then
  ( cd "$ROOT/src-tauri" && CARGO_TARGET_DIR="$TARGET" cargo build --release -p obsidium-cli )
fi

IFS=',' read -ra LIST <<< "$SIZES"
for count in "${LIST[@]}"; do
  vault="$VAULT_ROOT/vault-$count"
  data="$VAULT_ROOT/data-$count"
  if [ ! -d "$vault" ]; then
    node "$ROOT/scripts/bench/gen-vault.mjs" --out "$vault" --notes "$count" --folders 30 --large 2
  fi
  rm -rf "$data"
  echo "-- vault=$count cold (index build) --"
  OBSIDIUM_DATA_DIR="$data" /usr/bin/time -l "$CLI" search "architecture topic" \
    --workspace "$vault" --limit 5 2>&1 | grep -E "real|maximum resident"
  echo "-- vault=$count warm --"
  for _ in 1 2 3; do
    OBSIDIUM_DATA_DIR="$data" /usr/bin/time -l "$CLI" search "architecture topic" \
      --workspace "$vault" --limit 5 2>&1 | grep -E "real|maximum resident"
  done
  echo "-- vault=$count on-disk --"
  du -sh "$data"/headless-cli/search-v2/*/ 2>/dev/null || true
done

echo "== 3. Tauri app process (macOS) =="
if [ "$(uname -s)" = "Darwin" ]; then
  home="$VAULT_ROOT/home"
  mkdir -p "$home/Library/Application Support"
  "$ROOT/scripts/bench/measure-app.sh" --home "$home" --label cold-$(echo "$SIZES" | cut -d, -f1) --seconds 20 || true
else
  echo "skipped: not macOS"
fi

echo "== done; raw logs in $BENCH_OUT =="
